program.compute:
options = read('/input/options')
existing = read('/output/selection')
if valid(existing):
    result = existing
else:
    result = []
    for group in combinations(options, 3):
        ids = [record['id'] for record in group]
        if valid(ids):
            result = ids
            break

program.effects:
if not exists('/output/selection'):
    write('/output/selection', result)
if receipt('report') != 'success':
    if receipt('report') == 'unknown':
        status('report')
    if receipt('report') == 'unattempted' or receipt('report') == 'failure':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

